#define uvPanY  (iMouse.z <= 0.0 ? 0. : iMouse.y / iResolution.y * 3.)
#define uvPanX  (iMouse.y <= 0.0 ? 0. : iMouse.x / iResolution.x * 3.)

vec3 InitializeHexGrid(in vec2 uv, in float sharpness){
    // Skew UV
    uv.x -= uv.y * 0.5;


    // RGB Square GRID
    vec3 rgbSquareGrid = round(fract(((floor(uv.x) - floor(uv.y)) + vec3(0.,1.,2.)) / 3. + 1.666667));

    // Hex Gradients
    float hexGrad1 = (fract(uv.x) + fract(uv.y)) - 1.;

    vec2 hexGrad2 = uv.yx;
    hexGrad2 = 1. - hexGrad2;
    hexGrad2 = fract(hexGrad2);

    vec2 hexGrad3GB = vec2(0.);

    if (hexGrad1 > 0.){
        hexGrad3GB = hexGrad2;
    }else{
        hexGrad3GB = fract(uv);
    }
    vec3 hexGrad3 = vec3(abs(hexGrad1), hexGrad3GB);

    // Hex grid RGB
    vec3 hexGridRGB = vec3(dot(hexGrad3, rgbSquareGrid), dot(hexGrad3, rgbSquareGrid.yzx), dot(hexGrad3, rgbSquareGrid.zxy));
    // Sharpen
    hexGridRGB = pow(hexGridRGB, vec3(sharpness));
    hexGridRGB = hexGridRGB / dot(hexGridRGB, vec3(1.));

    return hexGridRGB;
}

vec2 rotate_2d(vec2 p_input, float p_theta)
{
    vec2 mul = vec2(0.);

    mat2 l_rot_matrix = mat2(cos(p_theta), -sin(p_theta),
                                     sin(p_theta),  cos(p_theta));
    mul = l_rot_matrix * p_input;
    return mul;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float sharpness = 5.0;

    // initilize UV
    vec2 uv = (fragCoord - iResolution.xy / 2.) / iResolution.y;
    // scale UV
    uv *= 8.;
    // mouse offset
    uv += vec2(uvPanX, uvPanY);

    // Make grid
    vec3 hexGridRGB = InitializeHexGrid(uv, sharpness);


    // Blend textures
    vec4 tex = texture(iChannel0, uv) * hexGridRGB.r;
    vec2 uv1 = rotate_2d(uv, 90.); 
    vec4 tex1 = texture(iChannel0, uv1) * hexGridRGB.g;
    vec2 uv2 = rotate_2d(uv, 270.); 
    vec4 tex2 = texture(iChannel0, uv2) * hexGridRGB.b;

    // Output to screen
    //Hexgrid debug
    //fragColor = vec4(hexGridRGB, 0.);
    // Normal Tiling
    //fragColor = texture(iChannel0, uv);
    // Hex tile texture
    fragColor = tex + tex1 + tex2;
}
